# MAGIC # Cost Observability — Materialized View Share Publisher
# MAGIC
# MAGIC Run this notebook with **Run All** in the workspace that owns the source
# MAGIC system tables. It creates the same nine app-managed aggregate tables used
# MAGIC by cost-obs, adds them to a Delta Share, and optionally grants an existing
# MAGIC recipient access to that share.
# MAGIC
# MAGIC **Required privileges**
# MAGIC - Read the referenced `system.*` tables
# MAGIC - `USE CATALOG` and `CREATE SCHEMA` on the target catalog
# MAGIC - `CREATE SHARE` on the metastore and ownership of the resulting share
# MAGIC - `SELECT` on every generated table
# MAGIC
# MAGIC The notebook is idempotent. Re-running replaces the aggregate data and
# MAGIC only adds tables that are not already present in the share.
# MAGIC
# MAGIC Contract: `e53b0cac0e8f776f1ff48ff29610c67ad7dbd1f296d8fd7f4da7ab7830be6221`

# COMMAND ----------

import json
import re
from typing import Any

spark: Any = globals().get("spark")
display: Any = globals().get("display")


def _widget(name: str, default: str, label: str) -> None:
    try:
        dbutils.widgets.get(name)  # noqa: F821
    except Exception:
        dbutils.widgets.text(name, default, label)  # noqa: F821


_widget("target_catalog", "main", "Target catalog")
_widget("target_schema", "cost_obs_shared", "Target schema")
_widget("share_name", "cost_obs_share", "Delta Share name")
_widget("recipient_name", "", "Existing recipient name (optional)")
_widget("lookback_days", "365", "Billing/query lookback days")

CATALOG = dbutils.widgets.get("target_catalog").strip()  # noqa: F821
SCHEMA = dbutils.widgets.get("target_schema").strip()  # noqa: F821
SHARE = dbutils.widgets.get("share_name").strip()  # noqa: F821
RECIPIENT = dbutils.widgets.get("recipient_name").strip()  # noqa: F821
LOOKBACK_DAYS = int(dbutils.widgets.get("lookback_days"))  # noqa: F821

_IDENTIFIER = re.compile(r"^[A-Za-z_][A-Za-z0-9_-]*$")
for field, value in {
    "target_catalog": CATALOG,
    "target_schema": SCHEMA,
    "share_name": SHARE,
}.items():
    if not _IDENTIFIER.fullmatch(value):
        raise ValueError(f"{field} must be a single catalog identifier: {value!r}")
if RECIPIENT and not _IDENTIFIER.fullmatch(RECIPIENT):
    raise ValueError("recipient_name must be a single recipient identifier")
if not 30 <= LOOKBACK_DAYS <= 1095:
    raise ValueError("lookback_days must be between 30 and 1095")

print(f"Publishing cost-obs aggregates to {CATALOG}.{SCHEMA}")
print(f"Delta Share: {SHARE}")
print(f"Recipient: {RECIPIENT or 'not granted by this run'}")

# COMMAND ----------

TABLE_SQL = json.loads('{"daily_usage_summary":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_usage_summary` CLUSTER BY (usage_date, workspace_id) AS\\nWITH usage_with_price AS (\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    u.sku_name,\\n    u.billing_origin_product,\\n    u.usage_quantity,\\n    u.identity_metadata.run_as AS run_as,\\n    COALESCE(p.pricing.default, 0) as price_per_dbu,\\n    COALESCE(p.pricing.effective_list.default, p.pricing.default, 0) as effective_price_per_dbu\\n  FROM system.billing.usage u\\n  LEFT JOIN LATERAL (\\n  SELECT\\n    ranked.pricing,\\n    ranked.price_start_time,\\n    ranked.price_end_time\\n  FROM (\\n    SELECT\\n      candidate.pricing,\\n      candidate.price_start_time,\\n      candidate.price_end_time,\\n      ROW_NUMBER() OVER (\\n        ORDER BY\\n          candidate.price_start_time DESC,\\n          COALESCE(candidate.price_end_time, TIMESTAMP \'9999-12-31 23:59:59\') ASC,\\n          COALESCE(candidate.pricing.effective_list.default, candidate.pricing.default, 0) DESC,\\n          COALESCE(candidate.pricing.default, 0) DESC,\\n          TO_JSON(candidate.pricing) DESC\\n      ) AS price_rank\\n    FROM system.billing.list_prices candidate\\n    WHERE candidate.sku_name = u.sku_name\\n      AND candidate.account_id = u.account_id\\n      AND candidate.cloud = u.cloud\\n      AND candidate.usage_unit = u.usage_unit\\n      AND candidate.currency_code = \'USD\'\\n      AND COALESCE(\\n        u.usage_start_time,\\n        CAST(u.usage_date AS TIMESTAMP)\\n      ) >= candidate.price_start_time\\n      AND (\\n        candidate.price_end_time IS NULL\\n        OR COALESCE(\\n          u.usage_start_time,\\n          CAST(u.usage_date AS TIMESTAMP)\\n        ) < candidate.price_end_time\\n      )\\n  ) ranked\\n  WHERE ranked.price_rank = 1\\n) p ON TRUE\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND u.usage_quantity > 0\\n)\\nSELECT\\n  usage_date,\\n  workspace_id,\\n  SUM(usage_quantity) as total_dbus,\\n  SUM(usage_quantity * price_per_dbu) as total_spend,\\n  SUM(usage_quantity * effective_price_per_dbu) as effective_list_spend,\\n  SUM(CASE WHEN run_as IS NOT NULL THEN usage_quantity * price_per_dbu ELSE 0 END) as user_attributed_spend\\nFROM usage_with_price\\nGROUP BY usage_date, workspace_id\\nORDER BY usage_date, workspace_id","daily_product_breakdown":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_product_breakdown` CLUSTER BY (usage_date, workspace_id) AS\\nWITH usage_with_price AS (\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    u.sku_name,\\n    u.billing_origin_product,\\n    u.usage_quantity,\\n    u.usage_metadata,\\n    COALESCE(p.pricing.default, 0) as price_per_dbu,\\n    COALESCE(p.pricing.effective_list.default, p.pricing.default, 0) as effective_price_per_dbu,\\n    CASE\\n      WHEN u.billing_origin_product = \'SQL\' THEN \'SQL\'\\n      WHEN u.billing_origin_product = \'DLT\' OR u.usage_metadata.dlt_pipeline_id IS NOT NULL THEN \'ETL - Streaming\'\\n      WHEN u.billing_origin_product = \'JOBS\' THEN \'ETL - Batch\'\\n      WHEN u.sku_name LIKE \'%ALL_PURPOSE%\' THEN \'Interactive\'\\n      WHEN u.billing_origin_product = \'SERVING\' OR u.billing_origin_product = \'MODEL_SERVING\'\\n           OR u.sku_name LIKE \'%SERVING%\' OR u.sku_name LIKE \'%INFERENCE%\'\\n           OR u.sku_name LIKE \'%PROVISIONED_THROUGHPUT%\' THEN \'Model Serving\'\\n      WHEN u.sku_name LIKE \'%VECTOR_SEARCH%\' THEN \'AI Search\'\\n      WHEN u.sku_name LIKE \'%FOUNDATION_MODEL%\' OR u.sku_name LIKE \'%FINE_TUNING%\' THEN \'Fine-Tuning\'\\n      WHEN u.sku_name LIKE \'%AI_BI%\' OR u.sku_name LIKE \'%AI_QUERY%\'\\n           OR u.sku_name LIKE \'%AI_FUNCTIONS%\' THEN \'AI Functions\'\\n      WHEN u.sku_name LIKE \'%SERVERLESS%\' AND u.billing_origin_product NOT IN (\'JOBS\', \'SQL\', \'DLT\') THEN \'Serverless\'\\n      ELSE \'Other\'\\n    END as product_category\\n  FROM system.billing.usage u\\n  LEFT JOIN LATERAL (\\n  SELECT\\n    ranked.pricing,\\n    ranked.price_start_time,\\n    ranked.price_end_time\\n  FROM (\\n    SELECT\\n      candidate.pricing,\\n      candidate.price_start_time,\\n      candidate.price_end_time,\\n      ROW_NUMBER() OVER (\\n        ORDER BY\\n          candidate.price_start_time DESC,\\n          COALESCE(candidate.price_end_time, TIMESTAMP \'9999-12-31 23:59:59\') ASC,\\n          COALESCE(candidate.pricing.effective_list.default, candidate.pricing.default, 0) DESC,\\n          COALESCE(candidate.pricing.default, 0) DESC,\\n          TO_JSON(candidate.pricing) DESC\\n      ) AS price_rank\\n    FROM system.billing.list_prices candidate\\n    WHERE candidate.sku_name = u.sku_name\\n      AND candidate.account_id = u.account_id\\n      AND candidate.cloud = u.cloud\\n      AND candidate.usage_unit = u.usage_unit\\n      AND candidate.currency_code = \'USD\'\\n      AND COALESCE(\\n        u.usage_start_time,\\n        CAST(u.usage_date AS TIMESTAMP)\\n      ) >= candidate.price_start_time\\n      AND (\\n        candidate.price_end_time IS NULL\\n        OR COALESCE(\\n          u.usage_start_time,\\n          CAST(u.usage_date AS TIMESTAMP)\\n        ) < candidate.price_end_time\\n      )\\n  ) ranked\\n  WHERE ranked.price_rank = 1\\n) p ON TRUE\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND u.usage_quantity > 0\\n)\\nSELECT\\n  usage_date,\\n  workspace_id,\\n  product_category,\\n  SUM(usage_quantity) as total_dbus,\\n  SUM(usage_quantity * price_per_dbu) as total_spend,\\n  SUM(usage_quantity * effective_price_per_dbu) as effective_list_spend\\nFROM usage_with_price\\nGROUP BY usage_date, workspace_id, product_category\\nORDER BY usage_date, workspace_id, product_category","daily_workspace_breakdown":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_workspace_breakdown` CLUSTER BY (usage_date, workspace_id) AS\\nWITH usage_with_price AS (\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    u.sku_name,\\n    u.usage_quantity,\\n    COALESCE(p.pricing.default, 0) as price_per_dbu,\\n    COALESCE(p.pricing.effective_list.default, p.pricing.default, 0) as effective_price_per_dbu\\n  FROM system.billing.usage u\\n  LEFT JOIN LATERAL (\\n  SELECT\\n    ranked.pricing,\\n    ranked.price_start_time,\\n    ranked.price_end_time\\n  FROM (\\n    SELECT\\n      candidate.pricing,\\n      candidate.price_start_time,\\n      candidate.price_end_time,\\n      ROW_NUMBER() OVER (\\n        ORDER BY\\n          candidate.price_start_time DESC,\\n          COALESCE(candidate.price_end_time, TIMESTAMP \'9999-12-31 23:59:59\') ASC,\\n          COALESCE(candidate.pricing.effective_list.default, candidate.pricing.default, 0) DESC,\\n          COALESCE(candidate.pricing.default, 0) DESC,\\n          TO_JSON(candidate.pricing) DESC\\n      ) AS price_rank\\n    FROM system.billing.list_prices candidate\\n    WHERE candidate.sku_name = u.sku_name\\n      AND candidate.account_id = u.account_id\\n      AND candidate.cloud = u.cloud\\n      AND candidate.usage_unit = u.usage_unit\\n      AND candidate.currency_code = \'USD\'\\n      AND COALESCE(\\n        u.usage_start_time,\\n        CAST(u.usage_date AS TIMESTAMP)\\n      ) >= candidate.price_start_time\\n      AND (\\n        candidate.price_end_time IS NULL\\n        OR COALESCE(\\n          u.usage_start_time,\\n          CAST(u.usage_date AS TIMESTAMP)\\n        ) < candidate.price_end_time\\n      )\\n  ) ranked\\n  WHERE ranked.price_rank = 1\\n) p ON TRUE\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND u.usage_quantity > 0\\n)\\nSELECT\\n  uwp.usage_date,\\n  uwp.workspace_id,\\n  ws.workspace_name,\\n  SUM(uwp.usage_quantity) as total_dbus,\\n  SUM(uwp.usage_quantity * uwp.price_per_dbu) as total_spend,\\n  SUM(uwp.usage_quantity * uwp.effective_price_per_dbu) as effective_list_spend\\nFROM usage_with_price uwp\\nLEFT JOIN system.access.workspaces_latest ws ON uwp.workspace_id = ws.workspace_id\\nGROUP BY uwp.usage_date, uwp.workspace_id, ws.workspace_name\\nORDER BY uwp.usage_date, uwp.workspace_id","sql_tool_attribution":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`sql_tool_attribution` CLUSTER BY (usage_date, workspace_id) AS\\nWITH sql_query_work AS (\\n  SELECT\\n    CASE\\n      WHEN client_application LIKE \'%Genie%\' THEN \'Genie\'\\n      ELSE \'DBSQL\'\\n    END AS sql_product,\\n    DATE(start_time) AS usage_date,\\n    workspace_id,\\n    compute.warehouse_id AS warehouse_id,\\n    SUM(total_task_duration_ms) AS work_ms\\n  FROM system.query.history\\n  WHERE executed_as_user_id IS NOT NULL\\n    AND compute.warehouse_id IS NOT NULL\\n    AND DATE(start_time) >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  GROUP BY 1, 2, 3, 4\\n),\\nsql_usage AS (\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    u.usage_metadata.warehouse_id as warehouse_id,\\n    SUM(u.usage_quantity) as total_dbus,\\n    SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) as total_spend,\\n    SUM(u.usage_quantity * COALESCE(p.pricing.effective_list.default, p.pricing.default, 0)) as effective_list_spend\\n  FROM system.billing.usage u\\n  LEFT JOIN LATERAL (\\n  SELECT\\n    ranked.pricing,\\n    ranked.price_start_time,\\n    ranked.price_end_time\\n  FROM (\\n    SELECT\\n      candidate.pricing,\\n      candidate.price_start_time,\\n      candidate.price_end_time,\\n      ROW_NUMBER() OVER (\\n        ORDER BY\\n          candidate.price_start_time DESC,\\n          COALESCE(candidate.price_end_time, TIMESTAMP \'9999-12-31 23:59:59\') ASC,\\n          COALESCE(candidate.pricing.effective_list.default, candidate.pricing.default, 0) DESC,\\n          COALESCE(candidate.pricing.default, 0) DESC,\\n          TO_JSON(candidate.pricing) DESC\\n      ) AS price_rank\\n    FROM system.billing.list_prices candidate\\n    WHERE candidate.sku_name = u.sku_name\\n      AND candidate.account_id = u.account_id\\n      AND candidate.cloud = u.cloud\\n      AND candidate.usage_unit = u.usage_unit\\n      AND candidate.currency_code = \'USD\'\\n      AND COALESCE(\\n        u.usage_start_time,\\n        CAST(u.usage_date AS TIMESTAMP)\\n      ) >= candidate.price_start_time\\n      AND (\\n        candidate.price_end_time IS NULL\\n        OR COALESCE(\\n          u.usage_start_time,\\n          CAST(u.usage_date AS TIMESTAMP)\\n        ) < candidate.price_end_time\\n      )\\n  ) ranked\\n  WHERE ranked.price_rank = 1\\n) p ON TRUE\\n  WHERE u.billing_origin_product = \'SQL\'\\n    AND u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND u.usage_quantity > 0\\n  GROUP BY 1, 2, 3\\n),\\nwarehouse_totals AS (\\n  SELECT\\n    usage_date,\\n    workspace_id,\\n    warehouse_id,\\n    SUM(work_ms) as total_work_ms\\n  FROM sql_query_work\\n  GROUP BY usage_date, workspace_id, warehouse_id\\n)\\nSELECT\\n  q.sql_product,\\n  q.usage_date,\\n  q.workspace_id,\\n  q.warehouse_id,\\n  CASE\\n    WHEN w.total_work_ms > 0 THEN (q.work_ms / w.total_work_ms) * s.total_dbus\\n    ELSE 0\\n  END as attributed_dbus,\\n  CASE\\n    WHEN w.total_work_ms > 0 THEN (q.work_ms / w.total_work_ms) * s.total_spend\\n    ELSE 0\\n  END as attributed_spend,\\n  CASE\\n    WHEN w.total_work_ms > 0 THEN (q.work_ms / w.total_work_ms) * s.effective_list_spend\\n    ELSE 0\\n  END as attributed_effective_list_spend\\nFROM sql_query_work q\\nJOIN warehouse_totals w ON q.usage_date = w.usage_date AND q.workspace_id = w.workspace_id AND q.warehouse_id = w.warehouse_id\\nLEFT JOIN sql_usage s ON q.usage_date = s.usage_date AND q.workspace_id = s.workspace_id AND q.warehouse_id = s.warehouse_id","daily_query_stats":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_query_stats` CLUSTER BY (usage_date, workspace_id) AS\\nSELECT\\n  DATE(start_time) as usage_date,\\n  workspace_id,\\n  COUNT(*) as total_queries,\\n  COUNT(DISTINCT COALESCE(executed_by, executed_as_user_id)) as unique_query_users,\\n  SUM(COALESCE(read_rows, 0)) as total_rows_read,\\n  SUM(COALESCE(read_bytes, 0)) as total_bytes_read,\\n  SUM(COALESCE(total_task_duration_ms, 0)) / 1000.0 as total_compute_seconds\\nFROM system.query.history\\nWHERE DATE(start_time) >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\nGROUP BY DATE(start_time), workspace_id\\nORDER BY usage_date, workspace_id","dbsql_cost_per_query":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`dbsql_cost_per_query` CLUSTER BY (query_date, workspace_id) AS\\nWITH\\n-- Get hourly DBU usage per warehouse from billing\\nwarehouse_hourly_usage AS (\\n  SELECT\\n    DATE_TRUNC(\'hour\', u.usage_start_time) AS hour_bucket,\\n    u.usage_metadata.warehouse_id AS warehouse_id,\\n    SUM(u.usage_quantity) AS hourly_dbus,\\n    SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS hourly_dollars,\\n    SUM(u.usage_quantity * COALESCE(p.pricing.effective_list.default, p.pricing.default, 0)) AS hourly_dollars_effective\\n  FROM system.billing.usage u\\n  LEFT JOIN LATERAL (\\n  SELECT\\n    ranked.pricing,\\n    ranked.price_start_time,\\n    ranked.price_end_time\\n  FROM (\\n    SELECT\\n      candidate.pricing,\\n      candidate.price_start_time,\\n      candidate.price_end_time,\\n      ROW_NUMBER() OVER (\\n        ORDER BY\\n          candidate.price_start_time DESC,\\n          COALESCE(candidate.price_end_time, TIMESTAMP \'9999-12-31 23:59:59\') ASC,\\n          COALESCE(candidate.pricing.effective_list.default, candidate.pricing.default, 0) DESC,\\n          COALESCE(candidate.pricing.default, 0) DESC,\\n          TO_JSON(candidate.pricing) DESC\\n      ) AS price_rank\\n    FROM system.billing.list_prices candidate\\n    WHERE candidate.sku_name = u.sku_name\\n      AND candidate.account_id = u.account_id\\n      AND candidate.cloud = u.cloud\\n      AND candidate.usage_unit = u.usage_unit\\n      AND candidate.currency_code = \'USD\'\\n      AND COALESCE(\\n        u.usage_start_time,\\n        CAST(u.usage_date AS TIMESTAMP)\\n      ) >= candidate.price_start_time\\n      AND (\\n        candidate.price_end_time IS NULL\\n        OR COALESCE(\\n          u.usage_start_time,\\n          CAST(u.usage_date AS TIMESTAMP)\\n        ) < candidate.price_end_time\\n      )\\n  ) ranked\\n  WHERE ranked.price_rank = 1\\n) p ON TRUE\\n  WHERE u.billing_origin_product = \'SQL\'\\n    AND u.usage_metadata.warehouse_id IS NOT NULL\\n    AND u.usage_start_time >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  GROUP BY 1, 2\\n),\\n-- Get all queries with their execution details\\nqueries_with_details AS (\\n  SELECT\\n    q.statement_id,\\n    q.statement_text,\\n    COALESCE(q.executed_by, q.executed_as_user_id) AS executed_by,\\n    q.compute.warehouse_id AS warehouse_id,\\n    q.workspace_id,\\n    q.start_time,\\n    q.end_time,\\n    (UNIX_TIMESTAMP(q.end_time) - UNIX_TIMESTAMP(q.start_time)) AS duration_seconds,\\n    q.total_task_duration_ms,\\n    q.client_application,\\n    -- Determine query source type from client_application and other fields\\n    CASE\\n      WHEN q.client_application LIKE \'%genie%\' OR q.client_application LIKE \'%Genie%\' THEN \'GENIE SPACE\'\\n      WHEN q.client_application LIKE \'%dashboard%\' OR q.client_application LIKE \'%Dashboard%\' THEN\\n        CASE\\n          WHEN q.client_application LIKE \'%lakeview%\' OR q.client_application LIKE \'%aibi%\' THEN \'AI/BI DASHBOARD\'\\n          ELSE \'LEGACY DASHBOARD\'\\n        END\\n      WHEN q.client_application LIKE \'%notebook%\' OR q.client_application LIKE \'%Notebook%\' THEN \'NOTEBOOK\'\\n      WHEN q.client_application LIKE \'%job%\' OR q.client_application LIKE \'%Job%\' OR q.statement_type = \'JOB\' THEN \'JOB\'\\n      WHEN q.client_application LIKE \'%alert%\' OR q.client_application LIKE \'%Alert%\' THEN \'ALERT\'\\n      WHEN q.client_application LIKE \'%sql-editor%\' OR q.client_application LIKE \'%SQL Editor%\' THEN \'SQL QUERY\'\\n      ELSE \'SQL QUERY\'\\n    END AS query_source_type,\\n    -- Extract source ID where possible\\n    CASE\\n      WHEN q.client_application LIKE \'%genie%\' THEN REGEXP_EXTRACT(q.client_application, \'genie[/-]([a-zA-Z0-9-]+)\', 1)\\n      WHEN q.client_application LIKE \'%dashboard%\' THEN REGEXP_EXTRACT(q.client_application, \'dashboard[/-]([a-zA-Z0-9-]+)\', 1)\\n      ELSE NULL\\n    END AS query_source_id\\n  FROM system.query.history q\\n  WHERE q.compute.warehouse_id IS NOT NULL\\n    AND q.start_time >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND q.statement_type != \'CANCEL\'\\n    AND (q.executed_by IS NOT NULL OR q.executed_as_user_id IS NOT NULL)\\n),\\n-- Calculate total work per warehouse per hour for proportional allocation\\nwarehouse_hourly_work AS (\\n  SELECT\\n    DATE_TRUNC(\'hour\', start_time) AS hour_bucket,\\n    warehouse_id,\\n    SUM(COALESCE(total_task_duration_ms, duration_seconds * 1000)) AS total_work_ms\\n  FROM queries_with_details\\n  GROUP BY 1, 2\\n),\\n-- Attribute costs to each query proportionally based on work done\\nquery_costs AS (\\n  SELECT\\n    q.statement_id,\\n    q.statement_text,\\n    q.executed_by,\\n    q.warehouse_id,\\n    q.workspace_id,\\n    q.start_time,\\n    q.end_time,\\n    q.duration_seconds,\\n    q.client_application,\\n    q.query_source_type,\\n    q.query_source_id,\\n    q.total_task_duration_ms,\\n    DATE_TRUNC(\'hour\', q.start_time) AS query_hour,\\n    -- Proportional cost attribution\\n    CASE\\n      WHEN w.total_work_ms > 0 THEN\\n        (COALESCE(q.total_task_duration_ms, q.duration_seconds * 1000) / w.total_work_ms) * h.hourly_dbus\\n      ELSE 0\\n    END AS query_attributed_dbus_estimation,\\n    CASE\\n      WHEN w.total_work_ms > 0 THEN\\n        (COALESCE(q.total_task_duration_ms, q.duration_seconds * 1000) / w.total_work_ms) * h.hourly_dollars\\n      ELSE 0\\n    END AS query_attributed_dollars_estimation,\\n    CASE\\n      WHEN w.total_work_ms > 0 THEN\\n        (COALESCE(q.total_task_duration_ms, q.duration_seconds * 1000) / w.total_work_ms) * h.hourly_dollars_effective\\n      ELSE 0\\n    END AS query_attributed_dollars_effective\\n  FROM queries_with_details q\\n  LEFT JOIN warehouse_hourly_work w\\n    ON DATE_TRUNC(\'hour\', q.start_time) = w.hour_bucket\\n    AND q.warehouse_id = w.warehouse_id\\n  LEFT JOIN warehouse_hourly_usage h\\n    ON DATE_TRUNC(\'hour\', q.start_time) = h.hour_bucket\\n    AND q.warehouse_id = h.warehouse_id\\n)\\nSELECT\\n  statement_id,\\n  query_source_id,\\n  query_source_type,\\n  client_application,\\n  executed_by,\\n  warehouse_id,\\n  statement_text,\\n  CAST(workspace_id AS STRING) AS workspace_id,\\n  start_time,\\n  end_time,\\n  duration_seconds,\\n  query_attributed_dollars_estimation,\\n  query_attributed_dbus_estimation,\\n  -- Generate query profile URL (customers should customize host)\\n  CONCAT(\\n    \'https://DATABRICKS_HOST/sql/history?o=\',\\n    CAST(workspace_id AS STRING),\\n    \'&queryId=\',\\n    statement_id,\\n    \'&queryStartTimeMs=\',\\n    CAST(UNIX_TIMESTAMP(start_time) * 1000 AS BIGINT)\\n  ) AS query_profile_url,\\n  -- Generate source URL for dashboards/genie spaces\\n  CASE\\n    WHEN query_source_type = \'GENIE SPACE\' AND query_source_id IS NOT NULL THEN\\n      CONCAT(\'https://DATABRICKS_HOST/genie/rooms/\', query_source_id)\\n    WHEN query_source_type = \'AI/BI DASHBOARD\' AND query_source_id IS NOT NULL THEN\\n      CONCAT(\'https://DATABRICKS_HOST/sql/dashboardsv3/\', query_source_id)\\n    WHEN query_source_type = \'LEGACY DASHBOARD\' AND query_source_id IS NOT NULL THEN\\n      CONCAT(\'https://DATABRICKS_HOST/sql/dashboards/\', query_source_id)\\n    WHEN query_source_type = \'SQL QUERY\' AND query_source_id IS NOT NULL THEN\\n      CONCAT(\'https://DATABRICKS_HOST/editor/queries/\', query_source_id)\\n    ELSE NULL\\n  END AS url_helper,\\n  DATE(start_time) AS query_date\\nFROM query_costs\\nWHERE query_attributed_dollars_estimation > 0\\n   OR query_attributed_dbus_estimation > 0\\n   OR duration_seconds > 0\\nORDER BY start_time DESC","daily_tag_summary":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_tag_summary` CLUSTER BY (usage_date, tag_key) AS\\nWITH tagged_usage AS (\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    u.usage_quantity,\\n    u.custom_tags,\\n    COALESCE(p.pricing.default, 0) AS price_per_dbu\\n  FROM system.billing.usage u\\n  LEFT JOIN LATERAL (\\n  SELECT\\n    ranked.pricing,\\n    ranked.price_start_time,\\n    ranked.price_end_time\\n  FROM (\\n    SELECT\\n      candidate.pricing,\\n      candidate.price_start_time,\\n      candidate.price_end_time,\\n      ROW_NUMBER() OVER (\\n        ORDER BY\\n          candidate.price_start_time DESC,\\n          COALESCE(candidate.price_end_time, TIMESTAMP \'9999-12-31 23:59:59\') ASC,\\n          COALESCE(candidate.pricing.effective_list.default, candidate.pricing.default, 0) DESC,\\n          COALESCE(candidate.pricing.default, 0) DESC,\\n          TO_JSON(candidate.pricing) DESC\\n      ) AS price_rank\\n    FROM system.billing.list_prices candidate\\n    WHERE candidate.sku_name = u.sku_name\\n      AND candidate.account_id = u.account_id\\n      AND candidate.cloud = u.cloud\\n      AND candidate.usage_unit = u.usage_unit\\n      AND candidate.currency_code = \'USD\'\\n      AND COALESCE(\\n        u.usage_start_time,\\n        CAST(u.usage_date AS TIMESTAMP)\\n      ) >= candidate.price_start_time\\n      AND (\\n        candidate.price_end_time IS NULL\\n        OR COALESCE(\\n          u.usage_start_time,\\n          CAST(u.usage_date AS TIMESTAMP)\\n        ) < candidate.price_end_time\\n      )\\n  ) ranked\\n  WHERE ranked.price_rank = 1\\n) p ON TRUE\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND u.usage_quantity > 0\\n    AND u.custom_tags IS NOT NULL\\n    AND size(u.custom_tags) > 0\\n),\\nexploded AS (\\n  SELECT\\n    usage_date,\\n    workspace_id,\\n    usage_quantity,\\n    price_per_dbu,\\n    tag_key,\\n    tag_value\\n  FROM tagged_usage\\n  LATERAL VIEW EXPLODE(custom_tags) t AS tag_key, tag_value\\n)\\nSELECT\\n  usage_date,\\n  workspace_id,\\n  tag_key,\\n  tag_value,\\n  SUM(usage_quantity)                    AS total_dbus,\\n  SUM(usage_quantity * price_per_dbu)    AS total_spend,\\n  COUNT(*)                               AS usage_row_count\\nFROM exploded\\nGROUP BY usage_date, workspace_id, tag_key, tag_value\\nORDER BY usage_date, tag_key, tag_value","daily_tag_coverage_summary":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_tag_coverage_summary` CLUSTER BY (usage_date, workspace_id) AS\\nWITH priced_usage AS (\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    u.usage_quantity,\\n    u.custom_tags,\\n    COALESCE(p.pricing.default, 0) AS price_per_dbu\\n  FROM system.billing.usage u\\n  LEFT JOIN LATERAL (\\n  SELECT\\n    ranked.pricing,\\n    ranked.price_start_time,\\n    ranked.price_end_time\\n  FROM (\\n    SELECT\\n      candidate.pricing,\\n      candidate.price_start_time,\\n      candidate.price_end_time,\\n      ROW_NUMBER() OVER (\\n        ORDER BY\\n          candidate.price_start_time DESC,\\n          COALESCE(candidate.price_end_time, TIMESTAMP \'9999-12-31 23:59:59\') ASC,\\n          COALESCE(candidate.pricing.effective_list.default, candidate.pricing.default, 0) DESC,\\n          COALESCE(candidate.pricing.default, 0) DESC,\\n          TO_JSON(candidate.pricing) DESC\\n      ) AS price_rank\\n    FROM system.billing.list_prices candidate\\n    WHERE candidate.sku_name = u.sku_name\\n      AND candidate.account_id = u.account_id\\n      AND candidate.cloud = u.cloud\\n      AND candidate.usage_unit = u.usage_unit\\n      AND candidate.currency_code = \'USD\'\\n      AND COALESCE(\\n        u.usage_start_time,\\n        CAST(u.usage_date AS TIMESTAMP)\\n      ) >= candidate.price_start_time\\n      AND (\\n        candidate.price_end_time IS NULL\\n        OR COALESCE(\\n          u.usage_start_time,\\n          CAST(u.usage_date AS TIMESTAMP)\\n        ) < candidate.price_end_time\\n      )\\n  ) ranked\\n  WHERE ranked.price_rank = 1\\n) p ON TRUE\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND u.usage_quantity > 0\\n)\\nSELECT\\n  usage_date,\\n  workspace_id,\\n  SUM(CASE WHEN custom_tags IS NOT NULL AND size(custom_tags) > 0\\n    THEN usage_quantity * price_per_dbu ELSE 0 END) AS tagged_spend,\\n  SUM(CASE WHEN custom_tags IS NULL OR size(custom_tags) = 0\\n    THEN usage_quantity * price_per_dbu ELSE 0 END) AS untagged_spend,\\n  SUM(usage_quantity * price_per_dbu) AS total_spend\\nFROM priced_usage\\nGROUP BY usage_date, workspace_id\\nORDER BY usage_date, workspace_id","daily_apps_summary":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_apps_summary` CLUSTER BY (usage_date, workspace_id) AS\\nSELECT\\n  u.usage_date,\\n  u.workspace_id,\\n  COALESCE(u.usage_metadata.app_id, \'Unknown\') AS app_id,\\n  u.sku_name,\\n  SUM(u.usage_quantity) AS total_dbus,\\n  SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS total_spend\\nFROM system.billing.usage u\\nLEFT JOIN LATERAL (\\n  SELECT\\n    ranked.pricing,\\n    ranked.price_start_time,\\n    ranked.price_end_time\\n  FROM (\\n    SELECT\\n      candidate.pricing,\\n      candidate.price_start_time,\\n      candidate.price_end_time,\\n      ROW_NUMBER() OVER (\\n        ORDER BY\\n          candidate.price_start_time DESC,\\n          COALESCE(candidate.price_end_time, TIMESTAMP \'9999-12-31 23:59:59\') ASC,\\n          COALESCE(candidate.pricing.effective_list.default, candidate.pricing.default, 0) DESC,\\n          COALESCE(candidate.pricing.default, 0) DESC,\\n          TO_JSON(candidate.pricing) DESC\\n      ) AS price_rank\\n    FROM system.billing.list_prices candidate\\n    WHERE candidate.sku_name = u.sku_name\\n      AND candidate.account_id = u.account_id\\n      AND candidate.cloud = u.cloud\\n      AND candidate.usage_unit = u.usage_unit\\n      AND candidate.currency_code = \'USD\'\\n      AND COALESCE(\\n        u.usage_start_time,\\n        CAST(u.usage_date AS TIMESTAMP)\\n      ) >= candidate.price_start_time\\n      AND (\\n        candidate.price_end_time IS NULL\\n        OR COALESCE(\\n          u.usage_start_time,\\n          CAST(u.usage_date AS TIMESTAMP)\\n        ) < candidate.price_end_time\\n      )\\n  ) ranked\\n  WHERE ranked.price_rank = 1\\n) p ON TRUE\\nWHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  AND u.usage_quantity > 0\\n  AND u.billing_origin_product = \'APPS\'\\nGROUP BY u.usage_date, u.workspace_id, COALESCE(u.usage_metadata.app_id, \'Unknown\'), u.sku_name\\nORDER BY u.usage_date, u.workspace_id"}')

spark.sql(f"CREATE SCHEMA IF NOT EXISTS `{CATALOG}`.`{SCHEMA}`")

build_results = []
for table_name, template in TABLE_SQL.items():
    print(f"Building {table_name} ...")
    try:
        spark.sql(
            template.format(
                catalog=CATALOG,
                schema=SCHEMA,
                billing_lookback_days=LOOKBACK_DAYS,
            )
        )
        row_count = spark.sql(
            f"SELECT COUNT(*) AS row_count FROM `{CATALOG}`.`{SCHEMA}`.`{table_name}`"
        ).first()["row_count"]
        build_results.append((table_name, "READY", int(row_count), None))
    except Exception as exc:
        build_results.append((table_name, "FAILED", 0, str(exc)))

failed = [row for row in build_results if row[1] == "FAILED"]
display(
    spark.createDataFrame(
        build_results,
        "table_name STRING, status STRING, row_count LONG, error STRING",
    )
)
if failed:
    raise RuntimeError(
        "Aggregate build failed: " + ", ".join(row[0] for row in failed)
    )

# COMMAND ----------

spark.sql(
    f"CREATE SHARE IF NOT EXISTS `{SHARE}` "
    "COMMENT 'Cost Observability managed aggregate tables'"
)

existing = {
    str(row.asDict().get("shared_object") or "").lower()
    for row in spark.sql(f"SHOW ALL IN SHARE `{SHARE}`").collect()
}
share_results = []
for table_name in TABLE_SQL:
    full_name = f"{CATALOG}.{SCHEMA}.{table_name}"
    if full_name.lower() not in existing:
        spark.sql(
            f"ALTER SHARE `{SHARE}` "
            f"ADD TABLE `{CATALOG}`.`{SCHEMA}`.`{table_name}`"
        )
        state = "ADDED"
    else:
        state = "ALREADY SHARED"
    share_results.append((table_name, state))

if RECIPIENT:
    spark.sql(f"GRANT SELECT ON SHARE `{SHARE}` TO RECIPIENT `{RECIPIENT}`")

display(
    spark.createDataFrame(
        share_results,
        "table_name STRING, share_status STRING",
    )
)

